SELECT status, CASE WHEN discount >= 0.34 THEN 'high' WHEN discount >= 0.06 THEN 'mid' ELSE 'low' END AS discount_bucket, COUNT(amount) AS amount_count, SUM(CASE WHEN channel = 'mobile' THEN discount ELSE 0 END) AS mobile_discount FROM orders WHERE channel = 'partner' GROUP BY status, CASE WHEN discount >= 0.34 THEN 'high' WHEN discount >= 0.06 THEN 'mid' ELSE 'low' END HAVING COUNT(amount) > 2 ORDER BY mobile_discount DESC
